patches.good:
diff --git a/src/attribution.ts b/src/attribution.ts
index 7eab20e..6e97b43 100644
--- a/src/attribution.ts
+++ b/src/attribution.ts
@@ -1,9 +1,36 @@
+function authorOf(rec: Record<string, unknown>): string {
+  return typeof rec.authored_by === "string" ? rec.authored_by : "";
+}
 export function classifyCommit(input: unknown): string {
-  void input;
-  throw new Error("not implemented");
+  if (typeof input !== "object" || input === null || Array.isArray(input)) {
+    return "unknown";
+  }
+  const rec = input as Record<string, unknown>;
+  if (rec.diff_empty === true) {
+    return "missed";
+  }
+  const author = authorOf(rec);
+  if (rec.hook_created === true || author.startsWith("bot-")) {
+    return "autocommit";
+  }
+  if (author === "") {
+    return "unknown";
+  }
+  return "model";
 }

-export function summarizeCommits(input: unknown): unknown {
-  void input;
-  throw new Error("not implemented");
+export function summarizeCommits(input: unknown): {
+  model: number;
+  autocommit: number;
+  missed: number;
+  unknown: number;
+} {
+  const counts = { model: 0, autocommit: 0, missed: 0, unknown: 0 };
+  if (Array.isArray(input)) {
+    for (const item of input) {
+      const kind = classifyCommit(item) as keyof typeof counts;
+      counts[kind] += 1;
+    }
+  }
+  return counts;
 }

